-- Allow cancel_line_item to cancel ordered items as well as approved items. When cancelling an item on a PO, close the PO if no active items remain.
CREATE OR REPLACE FUNCTION app_procurement.cancel_line_item(p_line_item_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = app_procurement, public AS $fn$ DECLARE v_req uuid; v_po uuid; v_remaining int; BEGIN IF NOT (public.check_user_permission(auth.uid(),'apps/procurement/approvals/act') OR public.check_user_permission(auth.uid(),'apps/procurement/purchasing/manage') OR public.check_user_permission(auth.uid(),'apps/procurement/admin/manage')) THEN RAISE EXCEPTION 'Not permitted to cancel'; END IF; UPDATE app_procurement.line_items SET status='cancelled', updated_at=now() WHERE id=p_line_item_id AND status IN ('approved','ordered') RETURNING request_id, po_id INTO v_req, v_po; IF v_req IS NULL THEN RAISE EXCEPTION 'Item not found or not approved/ordered'; END IF; IF v_po IS NOT NULL THEN SELECT count(*) INTO v_remaining FROM app_procurement.line_items WHERE po_id=v_po AND status NOT IN ('cancelled','received'); IF v_remaining = 0 THEN UPDATE app_procurement.purchase_orders SET status='closed', closed_at=now(), updated_at=now() WHERE id=v_po AND status='open'; END IF; END IF; PERFORM internal.proc_recompute_request_status(v_req); END; $fn$;
